import sys

def min_spots(n, H):
    if n == 0:
        return 0
    if H == 0:
        return 1

    current_height = H
    total_spots = 0
    remaining_sand = n

    while remaining_sand > 0:
        total_spots += 1
        remaining_sand -= current_height

        if remaining_sand >= 0:
            current_height -= 1
            if current_height < 0:
                current_height = 0
        else:
            remaining_sand += current_height
            current_height += 1

    return total_spots

